using System.ComponentModel.DataAnnotations;
using System.Text.Json.Nodes;
using FlowOps.Api.Errors;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.OpenApi;
using Microsoft.OpenApi;

namespace FlowOps.Api.OpenApi;

/// <summary>
/// The OpenAPI document is the executable contract (contracts/openapi.json, generated by
/// scripts/export-openapi.sh). These transformers make it say what the API really sends.
/// </summary>
public static class OpenApiSetup
{
    public const string DocumentName = "v1";

    public static IServiceCollection AddFlowOpsOpenApi(this IServiceCollection services) =>
        services.AddOpenApi(DocumentName, options =>
        {
            options.AddDocumentTransformer((document, _, _) =>
            {
                document.Info = new OpenApiInfo
                {
                    Title = "FlowOps API",
                    Version = "v1",
                    Description = "Generated from the API. Design contract: docs/API_CONTRACT.md.",
                };
                // Server URLs depend on the host that served the document; leaving them out keeps the export deterministic.
                document.Servers = [];
                RemoveNullFromRequiredInputReferences(document);
                return Task.CompletedTask;
            });
            options.AddSchemaTransformer(DescribeProblemExtensions);
            options.AddSchemaTransformer(RequireAllResponseProperties);
            options.AddSchemaTransformer(DescribeInputAttributes);
        });

    /// <summary>Every ProblemDetails we send carries <c>code</c> and <c>traceId</c> (API_CONTRACT.md §2).</summary>
    private static Task DescribeProblemExtensions(OpenApiSchema schema, OpenApiSchemaTransformerContext context, CancellationToken _)
    {
        if (!typeof(ProblemDetails).IsAssignableFrom(context.JsonTypeInfo.Type) || schema.Properties is null)
        {
            return Task.CompletedTask;
        }

        schema.Properties[ProblemDetailsSetup.CodeKey] = new OpenApiSchema
        {
            Type = JsonSchemaType.String,
            Description = "Stable error code, e.g. task.already_decided. The UI maps codes to messages.",
        };
        schema.Properties[ProblemDetailsSetup.TraceIdKey] = new OpenApiSchema { Type = JsonSchemaType.String };
        schema.Required ??= new HashSet<string>(StringComparer.Ordinal);
        schema.Required.Add(ProblemDetailsSetup.CodeKey);
        schema.Required.Add(ProblemDetailsSetup.TraceIdKey);
        return Task.CompletedTask;
    }

    /// <summary>
    /// Response DTOs always send every property (nullable ones as <c>null</c>), so mark them all required;
    /// otherwise generated TypeScript would make every field optional. Inputs keep their [Required] attributes.
    /// </summary>
    private static Task RequireAllResponseProperties(OpenApiSchema schema, OpenApiSchemaTransformerContext context, CancellationToken _)
    {
        var type = context.JsonTypeInfo.Type;
        if (context.JsonPropertyInfo is not null || !IsResponseDto(type) || schema.Properties is not { Count: > 0 })
        {
            return Task.CompletedTask;
        }

        schema.Required = new HashSet<string>(schema.Properties.Keys, StringComparer.Ordinal);
        return Task.CompletedTask;
    }

    /// <summary>
    /// A <c>[Required]</c> input property is never null on the wire, although its C# type is nullable so a
    /// missing value is caught by validation rather than defaulted. <c>[AllowedValues]</c> becomes an enum.
    /// </summary>
    private static Task DescribeInputAttributes(OpenApiSchema schema, OpenApiSchemaTransformerContext context, CancellationToken _)
    {
        var attributes = context.JsonPropertyInfo?.AttributeProvider;
        if (attributes is null)
        {
            return Task.CompletedTask;
        }

        if (attributes.IsDefined(typeof(RequiredAttribute), inherit: true))
        {
            if (schema.Type is { } type)
            {
                schema.Type = type & ~JsonSchemaType.Null;
            }

            if (schema.OneOf is { } alternatives)
            {
                foreach (var nullAlternative in alternatives.Where(s => s is OpenApiSchema { Type: JsonSchemaType.Null }).ToList())
                {
                    alternatives.Remove(nullAlternative);
                }
            }
        }

        if (attributes.GetCustomAttributes(typeof(AllowedValuesAttribute), inherit: true) is [AllowedValuesAttribute allowed])
        {
            schema.Enum = [.. allowed.Values.OfType<string>().Select(v => (JsonNode)JsonValue.Create(v))];
        }

        return Task.CompletedTask;
    }

    /// <summary>
    /// The generator wraps nullable object/enum properties as <c>oneOf: [null, $ref]</c> after schema transformers
    /// run, so required input references are unwrapped here, on the finished document.
    /// </summary>
    private static void RemoveNullFromRequiredInputReferences(OpenApiDocument document)
    {
        foreach (var (name, component) in document.Components?.Schemas ?? new Dictionary<string, IOpenApiSchema>())
        {
            if (!name.EndsWith("Request", StringComparison.Ordinal) || component is not OpenApiSchema { Properties: { } properties, Required: { } required })
            {
                continue;
            }

            foreach (var property in required.Where(properties.ContainsKey))
            {
                if (properties[property] is OpenApiSchema { OneOf: { Count: 2 } alternatives }
                    && alternatives.SingleOrDefault(a => a is OpenApiSchema { Type: JsonSchemaType.Null }) is { } nullAlternative)
                {
                    properties[property] = alternatives.Single(a => !ReferenceEquals(a, nullAlternative));
                }
            }
        }
    }

    private static bool IsResponseDto(Type type)
    {
        if (type.Assembly != typeof(Application.DependencyInjection).Assembly)
        {
            return false;
        }

        var name = type.IsGenericType ? type.Name[..type.Name.IndexOf('`', StringComparison.Ordinal)] : type.Name;
        return !name.EndsWith("Request", StringComparison.Ordinal)
            && !name.EndsWith("Query", StringComparison.Ordinal)
            && name != nameof(Application.Common.MoneyDto)
            && name != nameof(Application.Common.PageRequest);
    }

}
